                  </div>
                ) : (
                  <div className="note-options">&nbsp;</div>
                )}
              </div>
              {(activeFolder === Folder.ALL || activeFolder === Folder.FAVORITES) && (
                <div className="note-category">
                  {!!noteCategory ? (
                    <>
                      <FolderIcon size={12} className="context-menu-action" />
                      {noteCategory?.name}
                    </>
