import { createSlice, PayloadAction } from '@reduxjs/toolkit'

import { NoteItem, NotesState } from '@/types'
import { Folder } from '@/utils/enums'
import { createNote, getNoteTitle } from '@/utils/helpers'
import { loadState } from '@/utils/persist'

const savedState = loadState()

export const initialState: NotesState = savedState?.noteState ?? {
  notes: [],
  activeNoteId: '',
  selectedNotesIds: [],
  activeCategoryId: '',
  activeFolder: Folder.ALL,
  searchValue: '',
  error: '',
  loading: true,
}

const noteSlice = createSlice({
  name: 'note',
  initialState,
  reducers: {
    addNote: (state, action: PayloadAction<NoteItem>) => {
      state.notes = [action.payload, ...state.notes]
    },
    deleteNote: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.filter((note) => note.id !== action.payload)
    },
    swapNote: (state, action: PayloadAction<string>) => {
      state.activeNoteId = action.payload
    },
    updateNote: (state, action: PayloadAction<NoteItem>) => {
      state.notes = state.notes.map((note) =>
        note.id === action.payload.id ? action.payload : note
      )
    },
    updateActiveNote: (state, action: PayloadAction<{ noteId: string; multiSelect: boolean }>) => {
      const { noteId, multiSelect } = action.payload

      if (multiSelect) {
        state.selectedNotesIds = state.selectedNotesIds.includes(noteId)
          ? state.selectedNotesIds.filter((id) => id !== noteId)
          : [...state.selectedNotesIds, noteId]
      } else {
        state.activeNoteId = noteId
        state.selectedNotesIds = [noteId]
      }
    },
    updateSelectedNotes: (
      state,
      action: PayloadAction<{ noteId: string; multiSelect: boolean }>
    ) => {
      const { noteId, multiSelect } = action.payload

      if (multiSelect) {
        state.selectedNotesIds = state.selectedNotesIds.includes(noteId)
          ? state.selectedNotesIds.filter((id) => id !== noteId)
          : [...state.selectedNotesIds, noteId]
      } else {
        state.selectedNotesIds = [noteId]
      }
    },
    pruneNotes: (state) => {
      state.notes = state.notes.filter(
        (note) => note.id === state.activeNoteId || note.text !== ''
      )
    },
    searchNotes: (state, action: PayloadAction<string>) => {
      state.searchValue = action.payload
    },
    updateCategory: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === state.activeNoteId ? { ...note, category: action.payload } : note
      )
    },
    reassignCategory: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.category === action.payload ? { ...note, category: undefined } : note
      )
    },
    deleteNoteFromTrash: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.filter((note) => note.id !== action.payload)
    },
    addCategoryToNote: (state, action: PayloadAction<{ noteId: string; categoryId: string }>) => {
      const { noteId, categoryId } = action.payload
      state.notes = state.notes.map((note) =>
        note.id === noteId ? { ...note, category: categoryId } : note
      )
    },
    toggleFavoriteNote: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === action.payload ? { ...note, favorite: !note.favorite } : note
      )
    },
    toggleTrashedNote: (state, action: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === action.payload ? { ...note, trash: !note.trash } : note
      )
    },
    permanentlyEmptyTrash: (state) => {
      state.notes = state.notes.filter((note) => !note.trash)
    },
    restoreAllTrash: (state) => {
      state.notes = state.notes.map((note) => (note.trash ? { ...note, trash: false } : note))
    },
    updateNotes: (state, action: PayloadAction<NoteItem[]>) => {
      state.notes = action.payload
      state.loading = false
    },
    loadNotes: (state) => {
      state.loading = true
    },
    updateActiveFolder: (state, action: PayloadAction<Folder>) => {
      state.activeFolder = action.payload
      state.activeCategoryId = ''
      state.selectedNotesIds = []
    },
    updateActiveCategoryId: (state, action: PayloadAction<string>) => {
      state.activeCategoryId = action.payload
    },
    setError: (state, action: PayloadAction<string>) => {
      state.error = action.payload
    },
  },
})

export const {
  addNote,
  deleteNote,
  swapNote,
  updateNote,
  updateActiveNote,
  updateSelectedNotes,
  pruneNotes,
  searchNotes,
  updateCategory,
  reassignCategory,
  deleteNoteFromTrash,
  addCategoryToNote,
  toggleFavoriteNote,
  toggleTrashedNote,
  permanentlyEmptyTrash,
  restoreAllTrash,
  updateNotes,
  loadNotes,
  updateActiveFolder,
  updateActiveCategoryId,
  setError,
} = noteSlice.actions

export default noteSlice.reducer
