  const [isToggled, togglePreviewIcon] = useState<boolean>(false)

  // ===========================================================================
  // Hooks
  // ===========================================================================

  const { copiedText: uuidCopiedText, handleCopy } = useCopyToClipboard(successfulCopyMessage, 3000)

