            data-testid={TestID.UUID_MENU_BAR_COPY_ICON}
          >
            {copyNoteIcon}
            {uuidCopiedText && <span className="uuid-copied-text">{uuidCopiedText}</span>}
            <span className="sr-only">Copy note</span>
